import React from "react";
import "./../css/form.css";
import {
  FaUser,
  FaPhone,
  FaMapMarkerAlt,
  FaImage,
  FaTag,
  FaQuestionCircle,
  FaClock,
  FaLink,
} from "react-icons/fa";

import DatePicker from "react-multi-date-picker";
import persian from "react-date-object/calendars/persian";
import persian_fa from "react-date-object/locales/persian_fa";

class CustomerRequestForm extends React.Component {
  constructor(props) {
    super(props);

    this.state = {
      fullName: "",
      mobile: "",
      landline: "",
      province: "",
      address: "",
      deviceType: "",
      deviceBrand: "",
      deviceIssue: "",
      visitTime: "",
      description: "",

      states: [],
      deviceTypes: [],
      deviceBrands: [],

      loadingData: true,
      submitting: false,
    };

    this.handleChange = this.handleChange.bind(this);
    this.handleSubmit = this.handleSubmit.bind(this);
    this.loadData = this.loadData.bind(this);
  }

  componentDidMount() {
    this.loadData();
  }

  getToken() {
    return localStorage.getItem("token");
  }

  async loadData() {
    try {
      this.setState({
        loadingData: true,
      });

      const token = this.getToken();

      const [statesResponse, typesResponse] = await Promise.all([
        fetch("https://iranaserviceapp.ir/test/api/cities", {
          method: "GET",
          headers: {
            Accept: "application/json",
            ...(token
              ? {
                  Authorization: `Bearer ${token}`,
                }
              : {}),
          },
        }),

        fetch("https://iranaserviceapp.ir/test/api/list-type", {
          method: "GET",
          headers: {
            Accept: "application/json",
            ...(token
              ? {
                  Authorization: `Bearer ${token}`,
                }
              : {}),
          },
        }),
      ]);

      const statesData = await statesResponse.json();
      const typesData = await typesResponse.json();

      this.setState({
        states: statesData.states || [],
        deviceTypes: typesData.types || [],
        deviceBrands: typesData.brands || [],
        loadingData: false,
      });
    } catch (error) {
      console.error("Load data error:", error);

      this.setState({
        loadingData: false,
      });
    }
  }

  handleChange(field) {
    return (e) => {
      this.setState({
        [field]: e.target.value,
      });
    };
  }

  handleSubmit(e) {
    e.preventDefault();

    const {
      fullName,
      mobile,
      landline,
      province,
      address,
      deviceType,
      deviceBrand,
      deviceIssue,
      visitTime,
      description,
    } = this.state;

    const token = this.getToken();

    let user = null;

    try {
      const savedUser = localStorage.getItem("user");

      if (savedUser) {
        user = JSON.parse(savedUser);
      }
    } catch (error) {
      console.error("User parse error:", error);
    }

    const requestData = {
      name: fullName,
      mobile: mobile,
      mobile2: landline,
      state: province,
      device_brand: deviceBrand,
      device_type: deviceType,
      address: address,
      problem: deviceIssue,
      description: description,
      time: visitTime,
    };

    if (user && user.code) {
      requestData.code = user.code;
    }

    console.log("Data sent to API:", requestData);

    this.setState({
      submitting: true,
    });

    fetch("https://iranaserviceapp.ir/test/api/create", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Accept: "application/json",
        ...(token
          ? {
              Authorization: `Bearer ${token}`,
            }
          : {}),
      },
      body: JSON.stringify(requestData),
    })
      .then((response) => response.json())
      .then((data) => {
        console.log("Create response:", data);

        this.setState({
          submitting: false,
        });

        if (data.status === "1") {
          this.setState({
            fullName: "",
            mobile: "",
            landline: "",
            province: "",
            address: "",
            deviceType: "",
            deviceBrand: "",
            deviceIssue: "",
            visitTime: "",
            description: "",
          });
        }
      })
      .catch((error) => {
        console.error("Create request error:", error);

        this.setState({
          submitting: false,
        });
      });
  }

  render() {
    const {
      fullName,
      mobile,
      landline,
      province,
      address,
      deviceType,
      deviceBrand,
      deviceIssue,
      visitTime,
      description,
      states,
      deviceTypes,
      deviceBrands,
      loadingData,
      submitting,
    } = this.state;

    return (
      <div className="container pt-3">
        <div
          className="mx-auto"
          style={{
            maxWidth: "480px",
          }}
        >
          <h6 className="text-center fw-bold text-dark mb-4">
            اطلاعات مشتری را با دقت ثبت کنید
          </h6>

          <form onSubmit={this.handleSubmit}>
            {/* نام کامل */}
            <div className="custom-input mb-3">
              <div className="custom-icon">
                <FaUser />
              </div>

              <input
                type="text"
                placeholder="نام کامل"
                value={fullName}
                onChange={this.handleChange("fullName")}
              />
            </div>

            {/* شماره موبایل */}
            <div className="custom-input mb-3">
              <div className="custom-icon">
                <FaPhone />
              </div>

              <input
                type="tel"
                inputMode="numeric"
                placeholder="شماره موبایل"
                value={mobile}
                onChange={this.handleChange("mobile")}
              />
            </div>

            {/* تلفن ثابت */}
            <div className="custom-input mb-3">
              <div className="custom-icon">
                <FaPhone />
              </div>

              <input
                type="tel"
                inputMode="numeric"
                placeholder="تلفن ثابت"
                value={landline}
                onChange={this.handleChange("landline")}
              />
            </div>

            {/* استان */}
            <div className="custom-input mb-3">
              <div className="custom-icon">
                <FaMapMarkerAlt />
              </div>

              <select
                value={province}
                onChange={this.handleChange("province")}
                disabled={loadingData}
              >
                <option value="" disabled>
                  استان
                </option>

                {states.map((state) => (
                  <option key={state.id} value={state.id}>
                    {state.name}
                  </option>
                ))}
              </select>
            </div>

            {/* آدرس */}
            <div className="custom-input mb-3">
              <div className="custom-icon">
                <FaMapMarkerAlt />
              </div>

              <input
                type="text"
                placeholder="آدرس"
                value={address}
                onChange={this.handleChange("address")}
              />
            </div>

            {/* نوع دستگاه */}
            <div className="custom-input mb-3">
              <div className="custom-icon">
                <FaImage />
              </div>

              <select
                value={deviceType}
                onChange={this.handleChange("deviceType")}
                disabled={loadingData}
              >
                <option value="" disabled>
                  نوع دستگاه
                </option>

                {deviceTypes.map((type) => (
                  <option key={type.id} value={type.id}>
                    {type.name}
                  </option>
                ))}
              </select>
            </div>

            {/* برند دستگاه */}
            <div className="custom-input mb-3">
              <div className="custom-icon">
                <FaTag />
              </div>

              <select
                value={deviceBrand}
                onChange={this.handleChange("deviceBrand")}
                disabled={loadingData}
              >
                <option value="" disabled>
                  برند دستگاه
                </option>

                {deviceBrands.map((brand) => (
                  <option key={brand.id} value={brand.id}>
                    {brand.name}
                  </option>
                ))}
              </select>
            </div>

            {/* ایراد دستگاه */}
            <div className="custom-input mb-3">
              <div className="custom-icon">
                <FaQuestionCircle />
              </div>

              <input
                type="text"
                placeholder="ایراد دستگاه"
                value={deviceIssue}
                onChange={this.handleChange("deviceIssue")}
              />
            </div>

            {/* زمان مراجعه */}
            <div className="custom-input mb-3">
              <div className="custom-icon">
                <FaClock />
              </div>

              <DatePicker
                value={visitTime}
                onChange={(date) => {
                  this.setState({
                    visitTime: date
                      ? date.format("YYYY/MM/DD")
                      : "",
                  });
                }}
                calendar={persian}
                locale={persian_fa}
                format="YYYY/MM/DD"
                placeholder="0000/00/00"
                calendarPosition="top-right"
                inputClass="custom-date-input"
              />
            </div>

            {/* توضیحات */}
            <div className="custom-input mb-3">
              <div className="custom-icon">
                <FaLink />
              </div>

              <input
                type="text"
                placeholder="توضیحات"
                value={description}
                onChange={this.handleChange("description")}
              />
            </div>

            {/* دکمه */}
            <button
              type="submit"
              className="btn btn-sub w-100 fw-bold py-2 rounded-4"
              disabled={loadingData || submitting}
            >
              <small>
                {submitting ? "در حال ثبت..." : "ثبت درخواست"}
              </small>
            </button>
          </form>
        </div>
      </div>
    );
  }
}

export default CustomerRequestForm;
